// Key pair and signatures generated by perp-api's own reference signer (signApiRequest in
// perp-api src/auth/api-key-auth.ts) for the seed 0x01..0x20, so these tests pin the Go signer to
// the server's implementation rather than to itself.
const (
	goldenAPIKey    = "ebVWLo_mVPlAeLES6KmLp5AfhTrmlb7X4OORC60ElmQ"
	goldenAPISecret = "AQIDBAUGBwgJCgsMDQ4PEBESExQVFhcYGRobHB0eHyA"
)

func TestSignPayloadMatchesPerpAPIReference(t *testing.T) {
	cases := []struct {
		ts, method, uri, body, want string
	}{
		{
			ts: "1727000000000", method: "GET",
			uri:  "/v1/orders?size=500&status=INCOMPLETE&symbol=PERP_BTC_USDC",
			want: "WkG0Q5lWVk45SohSTVcSOKV-ANSWHDAodahkdJTUtNi2K1Ng2YvH7kNLWhTZhvHWvuxG13kxN6dfCYamAHJrBw",
		},
		{
			ts: "1727000000001", method: "POST", uri: "/v1/orders",
			body: `{"order_price":65000.5,"order_quantity":0.01,"order_type":"LIMIT","side":"BUY","symbol":"PERP_BTC_USDC"}`,
			want: "GtOkXJLWO0c0S2eM6vtjLZCryJTXPFdB-jPX0vVJvaCBIJfIBacb_LbMaiKw2UcAAXbxV4O0eaK0_MqIdSBmCw",
		},
	}
	for _, c := range cases {
		got, err := signPayload(goldenAPISecret, c.ts, c.method, c.uri, []byte(c.body))
		if err != nil {
			t.Fatal(err)
		}
		if got != c.want {
			t.Errorf("%s %s: signature\n got %s\nwant %s", c.method, c.uri, got, c.want)
		}
	}
}

func TestSignPayloadRejectsMalformedSecret(t *testing.T) {
	for _, secret := range []string{"", "not-base64!", base64.RawURLEncoding.EncodeToString(make([]byte, 31))} {
		if _, err := signPayload(secret, "1", "GET", "/", nil); err == nil {
			t.Errorf("secret %q: expected an error", secret)
		}
	}
}

func TestNextTimestampIsStrictlyIncreasingPerKey(t *testing.T) {
	a1 := nextTimestamp("key-a-"+t.Name(), 5000)
	a2 := nextTimestamp("key-a-"+t.Name(), 5000)
	a3 := nextTimestamp("key-a-"+t.Name(), 4000)
	b1 := nextTimestamp("key-b-"+t.Name(), 5000)
	if a1 != "5000" || a2 != "5001" || a3 != "5002" {
		t.Errorf("same key: got %s %s %s, want 5000 5001 5002", a1, a2, a3)
	}
	if b1 != "5000" {
		t.Errorf("other key must not be pushed ahead: got %s", b1)
	}
}

// ===============FAKE PERP-API=================

type recorded struct {
	method string
	uri    string
	body   string
	header http.Header
}

type fakePerpAPI struct {
	t        *testing.T
	mu       sync.Mutex
	routes   map[string]func() (int, string)
	requests []recorded
	seen     map[string]bool
}

// newFakePerpAPI serves canned responses keyed by "METHOD /path" (query excluded) and, like
// perp-api, refuses any signed request whose signature does not verify or repeats one it has seen.
func newFakePerpAPI(t *testing.T) (*fakePerpAPI, *FuturesClient) {
	f := &fakePerpAPI{t: t, routes: map[string]func() (int, string){}, seen: map[string]bool{}}
	srv := httptest.NewServer(http.HandlerFunc(f.serve))
	t.Cleanup(srv.Close)
	c := NewFuturesClient(goldenAPIKey, goldenAPISecret)
	c.BaseURL = srv.URL
	return f, c
}

func (f *fakePerpAPI) on(route string, status int, body string) {
	f.routes[route] = func() (int, string) { return status, body }
}

func (f *fakePerpAPI) serve(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(r.Body)
	f.mu.Lock()
	f.requests = append(f.requests, recorded{method: r.Method, uri: r.RequestURI, body: string(body), header: r.Header.Clone()})
	f.mu.Unlock()

	if sig := r.Header.Get("x-signature"); sig != "" {
		pub, _ := base64.RawURLEncoding.DecodeString(r.Header.Get("x-api-key"))
		raw, _ := base64.RawURLEncoding.DecodeString(sig)
		msg := r.Header.Get("x-timestamp") + "\n" + r.Method + "\n" + r.RequestURI + "\n" + string(body)
		if len(pub) != ed25519.PublicKeySize || !ed25519.Verify(pub, []byte(msg), raw) {
			w.WriteHeader(http.StatusUnauthorized)
			_, _ = w.Write([]byte(`{"message":"Invalid credentials","code":"UNAUTHORIZED"}`))
			return
		}
		f.mu.Lock()
		replay := f.seen[sig]
		f.seen[sig] = true
		f.mu.Unlock()
		if replay {
			w.WriteHeader(http.StatusUnauthorized)
			_, _ = w.Write([]byte(`{"message":"Replayed","code":"REPLAYED_REQUEST"}`))
			return
		}
	}

	route, ok := f.routes[r.Method+" "+r.URL.Path]
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`{"message":"no route","code":"NOT_FOUND"}`))
		return
	}
	status, resp := route()
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(resp))
}

func (f *fakePerpAPI) only(t *testing.T, method, path string) recorded {
	t.Helper()
	var hits []recorded
	for _, r := range f.requests {
		if r.method == method && strings.SplitN(r.uri, "?", 2)[0] == path {
			hits = append(hits, r)
		}
	}
	if len(hits) != 1 {
		t.Fatalf("%s %s: got %d requests, want 1", method, path, len(hits))
	}
	return hits[0]
}

func decodeBody(t *testing.T, r recorded) map[string]interface{} {
	t.Helper()
	dec := json.NewDecoder(strings.NewReader(r.body))
	dec.UseNumber()
	var m map[string]interface{}
	if err := dec.Decode(&m); err != nil {
		t.Fatalf("body %q: %v", r.body, err)
	}
	return m
}

var ctx = context.Background()

// ===============TRANSPORT=================

func TestTransportSignsAndSendsExactBytes(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("GET /v1/orders", 200, `{"rows":[]}`)
	f.on("GET /v1/algo-orders", 200, `{"rows":[]}`)

	if _, err := c.NewGetOrderList().Symbol("PERP_BTC_USDC").Do(ctx); err != nil {
		t.Fatal(err)
	}
	r := f.only(t, "GET", "/v1/orders")
	if r.uri != "/v1/orders?size=500&status=INCOMPLETE&symbol=PERP_BTC_USDC" {
		t.Errorf("uri = %s", r.uri)
	}
	if r.header.Get("x-api-key") != goldenAPIKey || r.header.Get("x-timestamp") == "" {
		t.Errorf("missing auth headers: %v", r.header)
	}
	if r.header.Get("Content-Type") != "" {
		t.Errorf("a bodiless request must not claim a JSON body, got %q", r.header.Get("Content-Type"))
	}
}

func TestConcurrentIdenticalRequestsAreNotReplays(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("GET /v1/positions", 200, `{"rows":[],"free_collateral":0,"total_collateral_value":0}`)

	var wg sync.WaitGroup
	errs := make(chan error, 20)
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, err := c.NewGetPositions().Do(ctx)
			errs <- err
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Fatal(err)
		}
	}
}

func TestErrorsCarryPerpAPICodeAndAreNotRetried(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("GET /v1/positions", 502, `{"message":"Orderly is unavailable","code":"ORDERLY_ERROR"}`)

	_, err := c.NewGetPositions().Do(ctx)
	if err == nil || !strings.Contains(err.Error(), "ORDERLY_ERROR") || !strings.Contains(err.Error(), "Orderly is unavailable") {
		t.Fatalf("err = %v", err)
	}
	if !isAPIErrorCode(err, 502, "ORDERLY_ERROR") {
		t.Errorf("err is not a typed apiError: %#v", err)
	}
	f.only(t, "GET", "/v1/positions")
}

func TestNonJSONErrorBodyIsBounded(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("GET /v1/positions", 502, "<html>"+strings.Repeat("x", 2000)+"</html>")

	_, err := c.NewGetPositions().Do(ctx)
	if err == nil || !strings.Contains(err.Error(), "(truncated)") || len(err.Error()) > 700 {
		t.Fatalf("err = %v", err)
	}
}

func TestUnconfiguredHostFailsClosed(t *testing.T) {
	SetBaseURLs("", "")
	c := NewFuturesClient(goldenAPIKey, goldenAPISecret)
	if _, err := c.NewGetPositions().Do(ctx); err != errHostNotConfigured {
		t.Fatalf("err = %v", err)
	}

	SetBaseURLs("https://perp.example/", "")
	t.Cleanup(func() { SetBaseURLs("", "") })
	c = NewFuturesClient(goldenAPIKey, goldenAPISecret)
	if c.BaseURL != "https://perp.example" {
		t.Errorf("BaseURL = %q", c.BaseURL)
	}
	c.SetDemo(true)
	if _, err := c.NewGetPositions().Do(ctx); err != errHostNotConfigured {
		t.Fatalf("demo without a demo host: err = %v", err)
	}
}

