func TestAccountInfo(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("GET /v1/account/info", 200, `{"account_id":"0xabc","max_leverage":10,"taker_fee_rate":5,"maker_fee_rate":2}`)

	got, err := c.NewGetAccountInfo().Do(ctx)
	if err != nil {
		t.Fatal(err)
	}
	want := entity.AccountInformation{UID: "0xabc", IP: "0.0.0.0/0", CanRead: true, CanTrade: true, PermFutures: true}
	if got.UID != want.UID || !got.CanRead || !got.CanTrade || got.CanTransfer || got.PermSpot || !got.PermFutures {
		t.Errorf("got %+v", got)
	}
}

func TestSignAuthStreamCarriesOrderlyLogin(t *testing.T) {
	f, c := newFakePerpAPI(t)
	f.on("POST /v1/account/stream-signature", 200, `{"accountId":"0xabc","orderlyKey":"ed25519:KEY","timestamp":1727000000000,"signature":"SIG","url":"wss://ws-private-evm.orderly.org/v2/ws/private/stream/0xabc"}`)

	got, err := c.NewSignAuthStream().Do(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if got.Signature != "SIG" || got.Timestamp != 1727000000000 || got.AccountID != "0xabc" || got.Key != "ed25519:KEY" || !strings.HasPrefix(got.URL, "wss://") {
		t.Errorf("got %+v", got)
	}
	if r := f.only(t, "POST", "/v1/account/stream-signature"); r.body != "" || r.header.Get("Content-Type") != "" {
		t.Errorf("stream-signature must go out bodiless, got body %q ct %q", r.body, r.header.Get("Content-Type"))
	}
}

