func TestDecimalHelpers(t *testing.T) {
	if got := plainDecimal("1e-7"); got != "0.0000001" {
		t.Errorf("plainDecimal = %s", got)
	}
	if got := plainDecimal("65000.5"); got != "65000.5" {
		t.Errorf("plainDecimal = %s", got)
	}
	if got := decimalPlaces("0.010"); got != "2" {
		t.Errorf("decimalPlaces = %s", got)
	}
	if got := maxLeverageFromIMR("0.02"); got != "50" {
		t.Errorf("maxLeverageFromIMR = %s", got)
	}
	if got := unrealizedPnl("-2", "90", "100"); got != "20" {
		t.Errorf("short unrealized = %s", got)
	}
}
